## 9. 性能优化

### 9.1 请求批处理

```typescript
// 批量处理多个请求
class RequestBatcher {
  private queue: Array<{
    model: Model;
    context: Context;
    resolve: (response: Response) => void;
    reject: (error: Error) => void;
  }> = [];

  private timer: NodeJS.Timeout | null = null;

  async request(model: Model, context: Context): Promise<Response> {
    return new Promise((resolve, reject) => {
      this.queue.push({ model, context, resolve, reject });

      // 批处理延迟
      if (!this.timer) {
        this.timer = setTimeout(() => this.flush(), 10);
      }
    });
  }

  private async flush() {
    const batch = this.queue.splice(0);
    this.timer = null;

    // 按提供商分组
    const byProvider = groupBy(batch, b => b.model.provider);

    // 并行发送到不同提供商
    await Promise.all(
      Object.entries(byProvider).map(async ([provider, requests]) => {
        // 某些提供商支持批量API
        if (supportsBatching(provider)) {
          return this.sendBatch(provider, requests);
        }

        // 否则并行发送
        return Promise.all(
          requests.map(r => 
            complete(r.model, r.context)
              .then(r.resolve)
              .catch(r.reject)
          )
        );
      })
    );
  }
}
```

