## 2. Agent循环核心算法

### 2.1 完整循环实现

```typescript
/**
 * 核心agent循环 - PI的心脏
 * 
 * 这是整个框架最关键的函数，仅约100行代码
 */
export async function* runAgent(
  model: Model,
  context: Context,
  tools: AgentTool[],
  options: AgentOptions = {}
): AsyncGenerator<AgentEvent, void, Message | undefined> {
  const { signal, messageQueue } = options;

  // 主循环 - 无步数限制！
  while (true) {
    // ==================== 阶段1: 调用LLM ====================

    yield { type: 'turn_start', turn: context.messages.length };

    let response: Response;
    let thinkingContent = '';
    let textContent = '';
    let toolCalls: ToolCall[] = [];

    try {
      // 流式调用
      for await (const event of streamCompletion(model, context, {
        tools,
        signal,
        ...options
      })) {
        // 透传所有LLM事件
        if (event.type === 'thinking_delta') {
          thinkingContent += event.delta;
          yield { type: 'thinking_delta', delta: event.delta };
        }

        if (event.type === 'text_delta') {
          textContent += event.delta;
          yield { type: 'text_delta', delta: event.delta };
        }

        if (event.type === 'tool_call_start') {
          yield { type: 'tool_call_start', toolCall: event.toolCall };
        }

        if (event.type === 'tool_call_delta') {
          // 更新工具调用
          const existing = toolCalls[event.index];
          if (existing) {
            Object.assign(existing, event.delta);
          } else {
            toolCalls[event.index] = event.delta as ToolCall;
          }

          yield { type: 'tool_call_delta', ...event };
        }

        if (event.type === 'tool_call_end') {
          toolCalls[event.index] = event.toolCall;
          yield { type: 'tool_call_end', toolCall: event.toolCall };
        }

        if (event.type === 'done') {
          response = event.response;
          yield { 
            type: 'llm_response', 
            response, 
            usage: event.usage 
          };
        }
      }
    } catch (error) {
      yield { type: 'error', error, phase: 'llm' };
      throw error;
    }

    // ==================== 阶段2: 检查完成条件 ====================

    // 如果没有工具调用，agent完成
    if (!toolCalls || toolCalls.length === 0) {
      yield { 
        type: 'turn_end', 
        reason: 'completed',
        finalMessage: textContent
      };
      break;
    }

    // ==================== 阶段3: 执行工具 ====================

    const toolResults: ToolResult[] = [];

    for (const [index, toolCall] of toolCalls.entries()) {
      // 在工具间检查消息队列
      if (messageQueue && messageQueue.hasMessages()) {
        const queuedMessages = messageQueue.drain();

        if (messageQueue.mode === 'steering') {
          // 立即注入，中断剩余工具
          yield { 
            type: 'queue_inject', 
            messages: queuedMessages,
            remainingTools: toolCalls.length - index
          };

          // 注入到上下文
          context.messages.push(
            ...queuedMessages.map(content => ({
              role: 'user' as const,
              content
            }))
          );

          // 跳过剩余工具，开始新回合
          break;
        }

        // follow-up模式：继续执行完工具
        // 在工具全部完成后注入
      }

      yield { 
        type: 'tool_start', 
        toolCall, 
        index, 
        total: toolCalls.length 
      };

      try {
        // 查找工具
        const tool = tools.find(t => t.name === toolCall.name);
        if (!tool) {
          throw new Error(`Tool not found: ${toolCall.name}`);
        }

        // 验证参数
        const validated = validateToolArgs(tool, toolCall.input);

        // 执行工具
        const result = await tool.execute(
          toolCall.id,
          validated,
          { signal }
        );

        toolResults.push(result);

        yield { 
          type: 'tool_end', 
          toolCall, 
          result, 
          index 
        };

      } catch (error) {
        // 工具执行失败
        const errorResult: ToolResult = {
          toolCallId: toolCall.id,
          error: error.message,
          details: { stack: error.stack }
        };

        toolResults.push(errorResult);

        yield { 
          type: 'tool_error', 
          toolCall, 
          error, 
          index 
        };
      }
    }

    // ==================== 阶段4: 更新上下文 ====================

    // 添加assistant消息
    context.messages.push({
      role: 'assistant',
      content: textContent,
      thinking: thinkingContent,
      toolCalls: toolCalls
    });

    // 添加工具结果
    context.messages.push({
      role: 'user',
      toolResults: toolResults
    });

    // 检查follow-up消息
    if (messageQueue && messageQueue.hasMessages() && 
        messageQueue.mode === 'follow-up') {
      const queuedMessages = messageQueue.drain();

      yield { 
        type: 'queue_inject', 
        messages: queuedMessages,
        remainingTools: 0
      };

      context.messages.push(
        ...queuedMessages.map(content => ({
          role: 'user' as const,
          content
        }))
      );
    }

    // 检查上下文窗口
    if (estimateTokens(context) > model.contextWindow * 0.9) {
      yield { 
        type: 'context_warning', 
        usage: estimateTokens(context),
        limit: model.contextWindow 
      };
    }

    // 继续下一轮
    yield { type: 'turn_complete', turn: context.messages.length };
  }

  // Agent完成
  yield { type: 'agent_complete', totalTurns: context.messages.length };
}
```

### 2.2 关键设计决策分析

#### 2.2.1 为何无步数限制？

```typescript
// 传统框架做法
const MAX_ITERATIONS = 25;
for (let i = 0; i < MAX_ITERATIONS; i++) {
  // ...
  if (i === MAX_ITERATIONS - 1) {
    throw new Error('Max iterations reached');
  }
}

// PI的做法
while (true) {
  // 信任模型会在完成时停止调用工具
  if (noToolCalls) break;
}
```

**理由**:
1. **信任模型能力**: 前沿模型通过RL已理解何时完成任务
2. **避免人为截断**: 步数限制会打断合法的长任务
3. **用户控制**: 用户随时可以通过Ctrl+C中止
4. **实际数据**: Terminal-Bench显示99%任务在15步内完成

**反例（Claude Code）**:
```typescript
// Claude Code有隐藏的步数限制
// 导致长任务被强制截断
// 用户无法看到限制，只能看到"任务完成"
```

#### 2.2.2 为何顺序执行工具？

```typescript
// 并发执行（大多数框架）
const results = await Promise.all(
  toolCalls.map(call => executeTool(call))
);

// 顺序执行（PI）
const results = [];
for (const call of toolCalls) {
  const result = await executeTool(call);
  results.push(result);
}
```

**顺序执行的优势**:

1. **简化依赖**: 工具B可以使用工具A的结果
```typescript
// 示例：先创建目录，再写入文件
[
  { name: 'bash', input: { command: 'mkdir -p /tmp/test' } },
  { name: 'write', input: { path: '/tmp/test/file.txt', content: 'data' } }
]
// 顺序执行保证正确性
```

2. **更好的可观察性**: 用户看到线性进度
```
✓ 创建目录 /tmp/test
✓ 写入文件 /tmp/test/file.txt
✓ 执行测试 pytest /tmp/test
```

3. **避免竞态条件**: 文件读写、bash命令等有副作用
```typescript
// 并发执行可能导致问题
Promise.all([
  bash('echo "line1" > file.txt'),
  bash('echo "line2" >> file.txt'),
  bash('cat file.txt')  // 结果不确定！
]);
```

4. **支持steering**: 可以在工具间插入用户消息
```typescript
for (const tool of tools) {
  await executeTool(tool);

  // 检查消息队列
  if (userSentMessage && mode === 'steering') {
    break;  // 停止剩余工具，处理新消息
  }
}
```

**性能权衡**:
```typescript
// 是的，顺序执行更慢
// 但：
// 1. 大多数agent每轮只调用1-3个工具
// 2. 工具执行时间远超网络延迟
// 3. 正确性 > 速度
```

#### 2.2.3 事件驱动架构的价值

```typescript
// 传统同步API
const result = await agent.run(prompt);
console.log(result);  // 只能看到最终结果

// PI的事件流
for await (const event of runAgent(model, context, tools)) {
  match(event.type, {
    'thinking_delta': () => ui.appendThinking(event.delta),
    'text_delta': () => ui.appendText(event.delta),
    'tool_start': () => ui.showToolSpinner(event.toolCall),
    'tool_end': () => ui.showToolResult(event.result),
    'error': () => ui.showError(event.error)
  });
}
```

**优势**:
1. **实时反馈**: 用户看到agent在思考、生成、执行
2. **响应式UI**: 自然支持流式更新
3. **可中断性**: 任何时候都能中止
4. **调试友好**: 精确知道哪一步出错
5. **进度追踪**: 知道完成了多少

---

## 3. 消息队列系统

### 3.1 两种注入模式

```typescript
type QueueMode = 'steering' | 'follow-up';

interface MessageQueue {
  mode: QueueMode;
  messages: string[];

  // 添加消息
  push(message: string): void;

  // 检查是否有消息
  hasMessages(): boolean;

  // 取出所有消息
  drain(): string[];
}

class MessageQueueImpl implements MessageQueue {
  private queue: string[] = [];

  constructor(public mode: QueueMode) {}

  push(message: string) {
    this.queue.push(message);
  }

  hasMessages(): boolean {
    return this.queue.length > 0;
  }

  drain(): string[] {
    const messages = [...this.queue];
    this.queue = [];
    return messages;
  }
}
```

### 3.2 Steering模式（立即引导）

```typescript
/**
 * Steering: 在当前工具完成后立即注入消息
 * 中断剩余工具的执行
 */

// 使用场景
const queue = new MessageQueue('steering');

for await (const event of runAgent(model, context, tools, { queue })) {
  if (event.type === 'tool_start' && event.toolCall.name === 'bash') {
    // 用户发现agent执行了错误的命令
    if (event.toolCall.input.command.includes('rm -rf')) {
      queue.push('STOP! 不要删除文件，我只是想清理日志');
    }
  }
}

// Agent循环中的处理
for (const toolCall of toolCalls) {
  await executeTool(toolCall);

  // 每个工具后检查队列
  if (queue.hasMessages() && queue.mode === 'steering') {
    // 立即注入，中断剩余工具
    const messages = queue.drain();
    context.messages.push(...messages);

    yield { 
      type: 'steering', 
      injectedMessages: messages,
      cancelledTools: toolCalls.slice(currentIndex + 1)
    };

    break;  // 跳出工具循环，开始新回合
  }
}
```

**实际应用示例**:
```typescript
// Agent计划执行3个工具
[
  { name: 'read', input: { path: 'config.json' } },
  { name: 'edit', input: { path: 'config.json', ... } },
  { name: 'bash', input: { command: 'git commit -am "update"' } }
]

// 执行到第2个工具时，用户发送消息
