### 3.3 Follow-up模式（任务后续）

```typescript
/**
 * Follow-up: 等待所有工具执行完成后注入消息
 * 用于在任务完成后添加新指令
 */

const queue = new MessageQueue('follow-up');

for await (const event of runAgent(model, context, tools, { queue })) {
  if (event.type === 'tool_end' && event.toolCall.name === 'write') {
    // Agent写完文件后，自动添加测试请求
    queue.push('现在为这个文件写单元测试');
  }

  if (event.type === 'turn_end') {
    // 任务完成，队列中的消息会在下一轮开始前注入
  }
}

// Agent循环中的处理
// 执行完所有工具
for (const toolCall of toolCalls) {
  await executeTool(toolCall);
}

// 回合结束时检查队列
if (queue.hasMessages() && queue.mode === 'follow-up') {
  const messages = queue.drain();
  context.messages.push(...messages);

  yield { 
    type: 'follow-up', 
    injectedMessages: messages 
  };

  // 继续agent循环，处理新消息
}
```

**实际应用示例**:
```typescript
// 自动化工作流
const queue = new MessageQueue('follow-up');

for await (const event of runAgent(model, context, tools, { queue })) {
  // 监听关键事件，自动添加后续步骤

  if (event.type === 'tool_end') {
    if (event.toolCall.name === 'write' && 
        event.toolCall.input.path.endsWith('.py')) {
