## 4. 上下文管理

### 4.1 上下文结构

```typescript
interface Context {
  // 对话历史
  messages: Message[];

  // 系统提示词（可选，默认使用模型内置）
  systemPrompt?: string;

  // 可用工具
  tools?: AgentTool[];

  // 元数据
  metadata?: {
    sessionId: string;
    createdAt: number;
    model: string;
    totalCost: number;
    totalTokens: number;
  };
}

type Message = 
  | UserMessage
  | AssistantMessage
  | ToolResultMessage;

interface UserMessage {
  role: 'user';
  content: string | ContentBlock[];
}

interface AssistantMessage {
  role: 'assistant';
  content: string;
  thinking?: string;           // Anthropic thinking
  toolCalls?: ToolCall[];
}

interface ToolResultMessage {
  role: 'user';
  toolResults: ToolResult[];
}
```

### 4.2 上下文大小估算

```typescript
/**
 * 快速估算token使用量
 * 用于上下文窗口管理
 */
function estimateTokens(context: Context): number {
  let total = 0;

  // 系统提示词
  if (context.systemPrompt) {
    total += estimateStringTokens(context.systemPrompt);
  }

  // 消息
  for (const message of context.messages) {
    if (message.role === 'user') {
      if (typeof message.content === 'string') {
        total += estimateStringTokens(message.content);
      } else {
        for (const block of message.content) {
          if (block.type === 'text') {
            total += estimateStringTokens(block.text);
          } else if (block.type === 'image') {
            // 图片token计算（粗略）
            total += 1000;  // 高分辨率图片约1000-2000 tokens
          }
        }
      }
    } else if (message.role === 'assistant') {
      total += estimateStringTokens(message.content);
      if (message.thinking) {
        total += estimateStringTokens(message.thinking);
      }
      if (message.toolCalls) {
        for (const call of message.toolCalls) {
          total += estimateStringTokens(JSON.stringify(call.input));
        }
      }
    } else {
      // 工具结果
      for (const result of message.toolResults) {
        if (result.output) {
          total += estimateStringTokens(result.output);
        }
        if (result.content) {
          for (const block of result.content) {
            if (block.type === 'text') {
              total += estimateStringTokens(block.text);
            }
          }
        }
      }
    }
  }

  // 工具定义
  if (context.tools) {
    for (const tool of context.tools) {
      total += estimateStringTokens(JSON.stringify({
        name: tool.name,
        description: tool.description,
        parameters: tool.parameters
      }));
    }
  }

  return total;
}

// 简单的字符串token估算（英文约4字符/token，中文约1.5字符/token）
function estimateStringTokens(str: string): number {
  const chineseChars = (str.match(/[\u4e00-\u9fa5]/g) || []).length;
  const otherChars = str.length - chineseChars;

  return Math.ceil(chineseChars / 1.5 + otherChars / 4);
}
```

### 4.3 上下文修剪触发

```typescript
/**
 * 在agent循环中监控上下文大小
 */
async function* runAgentWithPruning(
  model: Model,
  context: Context,
  tools: AgentTool[]
): AsyncGenerator<AgentEvent> {
  for await (const event of runAgent(model, context, tools)) {
    yield event;

    if (event.type === 'turn_complete') {
      const tokens = estimateTokens(context);
      const limit = model.contextWindow;

      // 达到90%阈值时警告
      if (tokens > limit * 0.9) {
        yield {
          type: 'context_warning',
          currentTokens: tokens,
          limit: limit,
          usage: (tokens / limit) * 100
        };
      }

      // 达到95%阈值时触发压缩
      if (tokens > limit * 0.95) {
        yield { type: 'compaction_start' };

        const compacted = await compactContext(context, model);

        yield {
          type: 'compaction_complete',
          before: tokens,
          after: estimateTokens(compacted),
          messagesRemoved: context.messages.length - compacted.messages.length
        };

        // 更新上下文
        context.messages = compacted.messages;
      }
    }
  }
}
```

