## 5. 事件系统详解

### 5.1 完整事件类型

```typescript
/**
 * PI Agent的事件类型系统
 * 所有事件都通过AsyncGenerator流式发送
 */
type AgentEvent =
  // ===== 回合生命周期 =====
  | { type: 'turn_start', turn: number }
  | { type: 'turn_complete', turn: number }
  | { type: 'turn_end', reason: 'completed' | 'max_tokens', finalMessage?: string }

  // ===== LLM响应 =====
  | { type: 'thinking_start' }
  | { type: 'thinking_delta', delta: string }
  | { type: 'thinking_end', thinking: string }
  | { type: 'text_start' }
  | { type: 'text_delta', delta: string }
  | { type: 'text_end', text: string }
  | { type: 'llm_response', response: Response, usage: TokenUsage }

  // ===== 工具调用 =====
  | { type: 'tool_call_start', toolCall: ToolCallStart, index: number }
  | { type: 'tool_call_delta', delta: Partial<ToolCall>, index: number }
  | { type: 'tool_call_end', toolCall: ToolCall, index: number }

  // ===== 工具执行 =====
  | { type: 'tool_start', toolCall: ToolCall, index: number, total: number }
  | { type: 'tool_end', toolCall: ToolCall, result: ToolResult, index: number }
  | { type: 'tool_error', toolCall: ToolCall, error: Error, index: number }

  // ===== 消息队列 =====
  | { type: 'queue_inject', messages: string[], remainingTools: number }
  | { type: 'steering', injectedMessages: string[], cancelledTools: ToolCall[] }
  | { type: 'follow-up', injectedMessages: string[] }

  // ===== 上下文管理 =====
  | { type: 'context_warning', currentTokens: number, limit: number, usage: number }
  | { type: 'compaction_start' }
  | { type: 'compaction_complete', before: number, after: number, messagesRemoved: number }

  // ===== 错误处理 =====
  | { type: 'error', error: Error, phase: 'llm' | 'tool' | 'validation' }

  // ===== 完成 =====
  | { type: 'agent_complete', totalTurns: number };
```

