```typescript
// 收集所有工具执行
async function collectToolExecutions(
  agentStream: AsyncGenerator<AgentEvent>
): Promise<ToolExecution[]> {
  const executions: ToolExecution[] = [];
  let current: Partial<ToolExecution> = {};

  for await (const event of agentStream) {
    if (event.type === 'tool_start') {
      current = {
        toolCall: event.toolCall,
        startTime: Date.now()
      };
    }

    if (event.type === 'tool_end') {
      executions.push({
        ...current,
        result: event.result,
        endTime: Date.now(),
        duration: Date.now() - current.startTime!
      } as ToolExecution);
    }
  }

  return executions;
}
