### 5.3 错误恢复策略

```typescript
/**
 * 错误恢复包装器
 */
async function* runAgentWithRetry(
  model: Model,
  context: Context,
  tools: AgentTool[],
  options: { maxRetries: number } = { maxRetries: 3 }
): AsyncGenerator<AgentEvent> {
  let retries = 0;

  while (retries <= options.maxRetries) {
    try {
      for await (const event of runAgent(model, context, tools)) {
        yield event;

        if (event.type === 'error') {
          if (event.phase === 'llm' && isRetryable(event.error)) {
            yield { 
              type: 'retry', 
              attempt: retries + 1,
              maxRetries: options.maxRetries,
              reason: event.error.message
            };

            retries++;

            // 等待指数退避
            await sleep(Math.pow(2, retries) * 1000);

            break;  // 重新开始agent循环
          } else {
            throw event.error;  // 不可重试的错误
          }
        }
      }

      // 成功完成
      break;

    } catch (error) {
      if (retries >= options.maxRetries) {
        yield { type: 'retry_exhausted', attempts: retries };
        throw error;
      }
    }
  }
}

function isRetryable(error: Error): boolean {
  return (
    error.message.includes('rate limit') ||
    error.message.includes('timeout') ||
    error.message.includes('503') ||
    error.message.includes('502')
  );
}
```

