## 6. 性能优化技巧

### 6.1 事件批处理

```typescript
/**
 * 批处理高频事件以减少UI更新
 */
async function* batchEvents(
  agentStream: AsyncGenerator<AgentEvent>,
  batchSize: number = 10,
  intervalMs: number = 100
): AsyncGenerator<AgentEvent[]> {
  let batch: AgentEvent[] = [];
  let timer: NodeJS.Timeout | null = null;

  const flush = () => {
    if (batch.length > 0) {
      const toYield = batch;
      batch = [];
      return toYield;
    }
    return null;
  };

  for await (const event of agentStream) {
    batch.push(event);

    // 达到批量大小立即flush
    if (batch.length >= batchSize) {
      if (timer) clearTimeout(timer);
      const flushed = flush();
      if (flushed) yield flushed;
      continue;
    }

    // 设置定时flush
    if (!timer) {
      timer = setTimeout(() => {
        timer = null;
        const flushed = flush();
        // 注意：无法在定时器中yield，需要在主循环中处理
      }, intervalMs);
    }
  }

  // 最终flush
  const final = flush();
  if (final) yield final;
}

// 使用
for await (const eventBatch of batchEvents(runAgent(...))) {
  // 批量处理事件，减少DOM操作
  ui.updateInBatch(eventBatch);
}
```

### 6.2 并行工具执行（高级）

```typescript
/**
 * 对于已知无副作用的工具，可以并行执行
 * 注意：这打破了PI的顺序执行原则，仅在特定场景使用
 */
interface ParallelToolConfig {
  // 标记为可并行的工具
  parallelizable: Set<string>;
}

async function executeToolsWithParallelism(
  toolCalls: ToolCall[],
  tools: AgentTool[],
  config: ParallelToolConfig
): Promise<ToolResult[]> {
  const results: ToolResult[] = new Array(toolCalls.length);
  const groups: { parallel: ToolCall[], sequential: ToolCall[] }[] = [];

  // 分组：连续的可并行工具合并
  let currentGroup: { parallel: ToolCall[], sequential: ToolCall[] } = {
    parallel: [],
    sequential: []
  };

  for (const call of toolCalls) {
    if (config.parallelizable.has(call.name)) {
      currentGroup.parallel.push(call);
    } else {
      if (currentGroup.parallel.length > 0) {
        groups.push(currentGroup);
        currentGroup = { parallel: [], sequential: [] };
      }
      currentGroup.sequential.push(call);
      groups.push(currentGroup);
      currentGroup = { parallel: [], sequential: [] };
    }
  }

  if (currentGroup.parallel.length > 0 || currentGroup.sequential.length > 0) {
    groups.push(currentGroup);
  }

  // 执行分组
  let index = 0;
  for (const group of groups) {
    // 并行执行
    if (group.parallel.length > 0) {
      const parallelResults = await Promise.all(
        group.parallel.map(call => executeTool(call, tools))
      );
      for (const result of parallelResults) {
        results[index++] = result;
      }
    }

    // 顺序执行
    for (const call of group.sequential) {
      results[index++] = await executeTool(call, tools);
    }
  }

  return results;
}

// 示例配置
const config: ParallelToolConfig = {
  parallelizable: new Set(['read'])  // read是幂等的，可并行
};

// 执行
// [read file1, read file2, write file3]
// → [read file1, read file2] 并行执行
// → write file3 顺序执行
```

